Q: How to compute the square root of a BigInt in JavaScript? A: <p>If reproducing the behaviour of the original Python code suffices for you, this should be enough:</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const num = 14564566644656456665555555555555555555555555545654645n;

console.log('%s', BigInt(Math.floor(Number(num) ** .5)));</code></pre>
</div>
</div>
</p>
<p>This is essentially what the Python code does; on a typical platform, where both languages use the same underlying floating-point implementation, the output should be identical.</p>
<p>The estimate obtained by this method will be rather rough, due to both imprecision during conversion to floating-point and subsequent rounding when the square root is computed.  If you want a more precise one, you may need to refine it.  Below code does so by the Newton–Heron method.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>const isqrt = (() =&gt; {
  const MAX_VALUE = BigInt(Number.MAX_VALUE);

  const isqrt0 = n =&gt; {
    if (n &lt;= MAX_VALUE)
      return BigInt(Math.floor(Number(n) ** .5));

    let a = 0n;
    let i = 0n;
    while (n &gt; 0n) {
      if (BigInt.asUintN(2, n)) {
        a |= 1n &lt;&lt; i;
      }
      i++;
      n &gt;&gt;= 2n;
    }
    return a;
  };

  return n =&gt; {
    if (n &lt; 0n)
      throw new RangeError(
        "Cannot compute a square root of a negative number");
    n = BigInt(n);
    let x = isqrt0(n);
    for (;;) {
      const sq0 = x * x;
      const sq1 = sq0 + ((x &lt;&lt; 1n) | 1n);
      if (sq0 &lt;= n &amp;&amp; n &lt; sq1)
        break;
      const d = (x - n / x) &gt;&gt; 1n;
      x -= d !== 0n ? d : BigInt((sq0 &gt; n) - (sq1 &lt;= n));
    }
    return x;
  };
})();

const num = 14564566644656456665555555555555555555555555545654645n;

console.log('%s', isqrt(num));</code></pre>
</div>
</div>
</p>
